/* =========================================================
   MARKET EXPANSION — USA & AUSTRALIA
   ---------------------------------------------------------
   276 listings added 2026-09-15 from manufacturer and
   specialist-retailer sources. Every part number, fitment,
   specification and price below was read from the source
   listing for that exact part number, not inferred.

   PRICING: `price` is the verified reference price at the
   source (MSRP where the manufacturer publishes one, else the
   specialist's listed price). applyPublicPrices() shows it
   struck through and sells at the public ratio, so the shelf
   price undercuts the market figure. No supplier cost, margin
   or invented "was" price appears anywhere in this file.

   IMAGES: manufacturer / retailer product photography for the
   exact part number, stored locally under /product-media and
   recorded in data/image-provenance.json with the original URL,
   the page it came from and the basis it was used on.
   DrivoraParts does not claim ownership of these images.

   STOCK: `stock: true` with no stockQty, matching the rest of
   the catalogue — the availability setup is unchanged.
========================================================= */

