    description: `ARB Air Locker RD163 for the Dana 60 Full-Float Rear, 30-Spline, 4.10 & Down — 1994–2003 Dodge Ram 2500 / 3500.

An ARB Air Locker is a selectable locking differential. Flick the dash switch and compressed air locks the differential gears, so both axle shafts turn with the ring gear and each wheel gets full drive. Switched off, it behaves like a normal open differential, so on-road driving and driveline wear are unaffected.

ARB's two-piece design has few moving parts, a patented timed locking mechanism for strength and fast unlocking, and a steel-reinforced elastomer-bonded seal built for temperature extremes. It can be engaged at any speed.

The kit includes the Air Locker differential, activation switch, solenoid valve, air line and bulkhead fitting. It needs an air compressor to operate, sold separately; ARB's own compressors are listed in this category. Fitting means removing the carrier and setting up the ring and pinion, so it's a job for a workshop with differential experience.

ARB matches each Air Locker to an axle, spline count and, for some axles, a gear-ratio range. Check your axle tag against the specifications below. The vehicle list is ARB's own application table for RD163.

Specifications

Manufacturer: ARB 4x4 Accessories
Product: Air Locker selectable locking differential
Axle: Full Float Dana 60
Position: Rear
Spline count: 30
Axle shaft diameter: 1.31 in
Gear ratio: 4.10 Down
Part number: RD163

Highlights

Full locking on demand, open differential when off
Can be engaged at any speed
Switch, solenoid and air line included
Air compressor required (sold separately)

Warranty
ARB 5-Year Warranty

Shipping
Worldwide Shipping Available`,
